// generated by timing.js: do not edit
(function () { const TL = {"DURATION":365.23,"lines":[{"at":1.2,"dur":1.28,"text":"You look up from the beach.","who":"narrator","scene":"beach"},{"at":2.74,"dur":1.38,"text":"A plane crosses the sky.","who":"narrator","scene":"beach"},{"at":4.38,"dur":1.58,"text":"You can read the name on its tail.","who":"narrator","scene":"beach"},{"at":6.22,"dur":1.17,"text":"And the pilot's face...","who":"narrator","scene":"beach"},{"at":7.94,"dur":0.46,"text":"waving.","who":"narrator","scene":"beach"},{"at":9.56,"dur":1.12,"text":"You glance at the Moon.","who":"narrator","scene":"moon"},{"at":10.94,"dur":2.13,"text":"Craters. Mountains. Shadows.","who":"narrator","scene":"moon"},{"at":13.33,"dur":0.86,"text":"No telescope.","who":"narrator","scene":"moon"},{"at":15.35,"dur":2.32,"text":"A friend points at a hill two kilometers away.","who":"narrator","scene":"hill"},{"at":18.13,"dur":0.61,"text":"What's that?","who":"friend","scene":"hill"},{"at":19.36,"dur":0.69,"text":"You squint.","who":"narrator","scene":"hill"},{"at":20.31,"dur":0.42,"text":"A man.","who":"narrator","scene":"hill"},{"at":20.99,"dur":0.94,"text":"Eating a sandwich.","who":"narrator","scene":"hill"},{"at":22.19,"dur":0.42,"text":"Ham...","who":"narrator","scene":"hill"},{"at":23.16,"dur":1.15,"text":"and too much mustard.","who":"narrator","scene":"hill"},{"at":25.47,"dur":0.79,"text":"Your name is Theo.","who":"narrator","scene":"plate"},{"at":26.52,"dur":2.8,"text":"A British driving test asks you to read a number plate...","who":"narrator","scene":"plate"},{"at":29.87,"dur":1.05,"text":"from twenty meters.","who":"narrator","scene":"plate"},{"at":31.18,"dur":0.3,"text":"You?","who":"narrator","scene":"plate"},{"at":31.9,"dur":0.78,"text":"Two kilometers.","who":"narrator","scene":"plate"},{"at":33.84,"dur":3.07,"text":"Normal eyes pick out details about one sixtieth of a degree wide.","who":"narrator","scene":"acuity"},{"at":37.17,"dur":0.32,"text":"Yours?","who":"narrator","scene":"acuity"},{"at":37.91,"dur":1.29,"text":"A hundred times finer.","who":"narrator","scene":"acuity"},{"at":40.36,"dur":0.91,"text":"But here's the rule.","who":"narrator","scene":"rule"},{"at":41.53,"dur":1.86,"text":"Your eyes got a hundred times sharper.","who":"narrator","scene":"rule"},{"at":43.65,"dur":0.91,"text":"Your legs did not.","who":"narrator","scene":"rule"},{"at":44.82,"dur":2.11,"text":"You can spot trouble two kilometers away.","who":"narrator","scene":"rule"},{"at":47.19,"dur":0.88,"text":"You still reach it...","who":"narrator","scene":"rule"},{"at":48.62,"dur":0.9,"text":"at human speed.","who":"narrator","scene":"rule"},{"at":50.68,"dur":2.65,"text":"So what if your eyesight was a hundred times sharper?","who":"narrator","scene":"title"},{"at":54.65,"dur":1.7,"text":"Plus: you never need glasses.","who":"narrator","scene":"class"},{"at":56.61,"dur":3.09,"text":"From the back row, you can read the teacher's notes on her desk.","who":"narrator","scene":"class"},{"at":59.96,"dur":0.37,"text":"Do you?","who":"narrator","scene":"class"},{"at":60.75,"dur":0.37,"text":"Never.","who":"narrator","scene":"class"},{"at":61.38,"dur":0.54,"text":"Mostly.","who":"narrator","scene":"class"},{"at":62.18,"dur":2.23,"text":"Minus: you can read everything else too.","who":"narrator","scene":"class"},{"at":64.67,"dur":1.06,"text":"Every pore on her nose.","who":"narrator","scene":"class"},{"at":65.99,"dur":0.8,"text":"Every grey hair...","who":"narrator","scene":"class"},{"at":67.34,"dur":1.55,"text":"she thinks nobody can see.","who":"narrator","scene":"class"},{"at":69.35,"dur":2.81,"text":"Okay, class. Why is Theo staring at me?","who":"teacher","scene":"class"},{"at":73.48,"dur":3.28,"text":"At the football match, you sit in the cheapest seat in the stadium.","who":"narrator","scene":"stadium"},{"at":77.02,"dur":1.89,"text":"You can still read the stitching on the ball.","who":"narrator","scene":"stadium"},{"at":80.07,"dur":2.75,"text":"In birdwatching club, everyone shares binoculars.","who":"narrator","scene":"birds"},{"at":83.08,"dur":1.01,"text":"You count the feathers...","who":"narrator","scene":"birds"},{"at":84.64,"dur":0.5,"text":"out loud.","who":"narrator","scene":"birds"},{"at":86.3,"dur":0.52,"text":"The catch?","who":"narrator","scene":"fovea"},{"at":87.24,"dur":2.48,"text":"Your sharpest vision only lives in one tiny spot.","who":"narrator","scene":"fovea"},{"at":89.98,"dur":1.54,"text":"Hold your thumb out at arm's length.","who":"narrator","scene":"fovea"},{"at":91.78,"dur":0.9,"text":"That tiny patch?","who":"narrator","scene":"fovea"},{"at":93.1,"dur":1.98,"text":"That's all your eyes see sharply at once.","who":"narrator","scene":"fovea"},{"at":95.34,"dur":0.96,"text":"So your eyes jump.","who":"narrator","scene":"fovea"},{"at":96.56,"dur":1.41,"text":"Three or four times a second.","who":"narrator","scene":"fovea"},{"at":98.23,"dur":0.86,"text":"Building the rest.","who":"narrator","scene":"fovea"},{"at":99.35,"dur":3.82,"text":"Except now, every jump brings in ten thousand times more detail.","who":"narrator","scene":"fovea"},{"at":103.43,"dur":0.75,"text":"And your brain...","who":"narrator","scene":"fovea"},{"at":104.73,"dur":1.04,"text":"has to sort all of it.","who":"narrator","scene":"fovea"},{"at":106.03,"dur":0.59,"text":"Headaches.","who":"narrator","scene":"fovea"},{"at":106.88,"dur":0.92,"text":"Every single day.","who":"narrator","scene":"fovea"},{"at":108.96,"dur":1.7,"text":"But where it gets really crazy...","who":"narrator","scene":"harbor"},{"at":111.21,"dur":0.58,"text":"is the video.","who":"narrator","scene":"harbor"},{"at":112.05,"dur":1.61,"text":"A tourist films you at the harbor.","who":"narrator","scene":"harbor"},{"at":113.92,"dur":2.63,"text":"You read a tiny warning sign on a ship far out at sea.","who":"narrator","scene":"harbor"},{"at":116.81,"dur":1.21,"text":"The clip goes everywhere.","who":"narrator","scene":"harbor"},{"at":119.18,"dur":1.2,"text":"By Friday, a message.","who":"narrator","scene":"message"},{"at":120.64,"dur":0.8,"text":"Mr. Black.","who":"narrator","scene":"message"},{"at":121.7,"dur":0.4,"text":"Polite.","who":"narrator","scene":"message"},{"at":122.36,"dur":0.35,"text":"Rich.","who":"narrator","scene":"message"},{"at":123.17,"dur":0.66,"text":"I have a job.","who":"black","scene":"message"},{"at":124.09,"dur":3.93,"text":"Sit in a café. Read a few phones. A few bank cards.","who":"black","scene":"message"},{"at":128.28,"dur":1.16,"text":"Nobody gets hurt.","who":"black","scene":"message"},{"at":129.7,"dur":1.38,"text":"Doesn't that sound easy?","who":"black","scene":"message"},{"at":132.4,"dur":0.84,"text":"And there's a cost.","who":"narrator","scene":"cost"},{"at":133.5,"dur":1.12,"text":"You can't switch it off.","who":"narrator","scene":"cost"},{"at":134.88,"dur":0.72,"text":"Peeling paint.","who":"narrator","scene":"cost"},{"at":135.86,"dur":0.97,"text":"Cracks in bridges.","who":"narrator","scene":"cost"},{"at":137.09,"dur":2.27,"text":"Mold in the bread before anyone else can see it.","who":"narrator","scene":"cost"},{"at":139.62,"dur":0.98,"text":"Your eyes never rest.","who":"narrator","scene":"cost"},{"at":140.86,"dur":1.98,"text":"And the world stops looking beautiful.","who":"narrator","scene":"cost"},{"at":143.1,"dur":0.9,"text":"It just looks...","who":"narrator","scene":"cost"},{"at":144.55,"dur":0.51,"text":"detailed.","who":"narrator","scene":"cost"},{"at":145.32,"dur":1.44,"text":"Sunsets turn into dust.","who":"narrator","scene":"cost"},{"at":147.02,"dur":1.35,"text":"Faces turn into maps.","who":"narrator","scene":"cost"},{"at":149.53,"dur":1.33,"text":"Then there's Grandpa Sam.","who":"narrator","scene":"grandpa"},{"at":151.12,"dur":1.81,"text":"He used to be a lifeguard on this beach.","who":"narrator","scene":"grandpa"},{"at":153.19,"dur":1.71,"text":"Now he has macular degeneration.","who":"narrator","scene":"grandpa"},{"at":155.16,"dur":0.86,"text":"It's a real disease.","who":"narrator","scene":"grandpa"},{"at":156.28,"dur":3.37,"text":"It slowly wipes out the center of your vision, while the edges stay.","who":"narrator","scene":"grandpa"},{"at":159.91,"dur":0.95,"text":"So you see the most.","who":"narrator","scene":"grandpa"},{"at":161.12,"dur":1.01,"text":"And he sees the least.","who":"narrator","scene":"grandpa"},{"at":163.29,"dur":2.33,"text":"Every Sunday, you climb the cliff together.","who":"narrator","scene":"cliff"},{"at":165.88,"dur":1.42,"text":"He flies his big red kite.","who":"narrator","scene":"cliff"},{"at":167.56,"dur":1.75,"text":"It's the one thing he still finds...","who":"narrator","scene":"cliff"},{"at":169.86,"dur":1.25,"text":"from the corner of his eye.","who":"narrator","scene":"cliff"},{"at":171.57,"dur":2.38,"text":"I can't see the gulls anymore, Theo.","who":"grandpa","scene":"cliff"},{"at":174.21,"dur":0.96,"text":"So you tell me.","who":"grandpa","scene":"cliff"},{"at":175.63,"dur":0.59,"text":"And you do.","who":"narrator","scene":"cliff"},{"at":176.48,"dur":0.62,"text":"Every wing.","who":"narrator","scene":"cliff"},{"at":177.36,"dur":0.56,"text":"Every wave.","who":"narrator","scene":"cliff"},{"at":178.18,"dur":1.16,"text":"You make a promise too.","who":"narrator","scene":"cliff"},{"at":179.8,"dur":0.68,"text":"If I can see it...","who":"theo","scene":"cliff"},{"at":181.03,"dur":1.01,"text":"it's mine to fix.","who":"theo","scene":"cliff"},{"at":183.2,"dur":0.81,"text":"Sunday comes.","who":"narrator","scene":"roof"},{"at":184.27,"dur":1.19,"text":"But you're not on the cliff.","who":"narrator","scene":"roof"},{"at":185.72,"dur":2.69,"text":"You're on a café roof, two kilometers down the coast.","who":"narrator","scene":"roof"},{"at":188.67,"dur":1.15,"text":"Mr. Black's job.","who":"narrator","scene":"roof"},{"at":190.08,"dur":1.92,"text":"Below you, a woman at a cash machine.","who":"narrator","scene":"roof"},{"at":192.26,"dur":0.46,"text":"Her card.","who":"narrator","scene":"roof"},{"at":192.98,"dur":0.47,"text":"Her keys.","who":"narrator","scene":"roof"},{"at":193.71,"dur":0.49,"text":"Her PIN.","who":"narrator","scene":"roof"},{"at":194.46,"dur":1.64,"text":"Mr. Black's voice in your ear.","who":"narrator","scene":"roof"},{"at":196.56,"dur":1.32,"text":"Four numbers, kid.","who":"black","scene":"roof"},{"at":198.14,"dur":0.79,"text":"Then you're done.","who":"black","scene":"roof"},{"at":200.09,"dur":0.38,"text":"Then...","who":"narrator","scene":"sea"},{"at":201.02,"dur":0.49,"text":"you see it.","who":"narrator","scene":"sea"},{"at":201.77,"dur":1.17,"text":"Far out past the beach.","who":"narrator","scene":"sea"},{"at":203.2,"dur":0.68,"text":"A small boy.","who":"narrator","scene":"sea"},{"at":204.14,"dur":0.87,"text":"On an orange board.","who":"narrator","scene":"sea"},{"at":205.27,"dur":0.63,"text":"Drifting...","who":"narrator","scene":"sea"},{"at":206.45,"dur":0.42,"text":"fast.","who":"narrator","scene":"sea"},{"at":207.13,"dur":1.47,"text":"The water around him is darker.","who":"narrator","scene":"sea"},{"at":208.86,"dur":0.47,"text":"Flatter.","who":"narrator","scene":"sea"},{"at":209.59,"dur":0.84,"text":"A rip current.","who":"narrator","scene":"sea"},{"at":210.69,"dur":2.42,"text":"Some rips move faster than an Olympic swimmer.","who":"narrator","scene":"sea"},{"at":213.37,"dur":1.55,"text":"Has anyone on the sand noticed?","who":"narrator","scene":"sea"},{"at":215.34,"dur":0.32,"text":"No.","who":"narrator","scene":"sea"},{"at":215.92,"dur":1.63,"text":"The lifeguard is looking the wrong way.","who":"narrator","scene":"sea"},{"at":217.81,"dur":0.78,"text":"Two kilometers.","who":"narrator","scene":"sea"},{"at":218.85,"dur":2.36,"text":"Even sprinting, you'd need six minutes.","who":"narrator","scene":"sea"},{"at":221.47,"dur":0.58,"text":"Maybe more.","who":"narrator","scene":"sea"},{"at":222.31,"dur":1.61,"text":"The board slips from his arms.","who":"narrator","scene":"sea"},{"at":225.08,"dur":0.34,"text":"Theo?","who":"black","scene":"choice"},{"at":225.84,"dur":1.44,"text":"The numbers. Now.","who":"black","scene":"choice"},{"at":227.74,"dur":1.07,"text":"You can see the PIN.","who":"narrator","scene":"choice"},{"at":229.07,"dur":0.91,"text":"You can see the boy.","who":"narrator","scene":"choice"},{"at":230.24,"dur":0.78,"text":"You can't have both.","who":"narrator","scene":"choice"},{"at":231.28,"dur":0.44,"text":"The money...","who":"narrator","scene":"choice"},{"at":232.27,"dur":0.47,"text":"or the boy.","who":"narrator","scene":"choice"},{"at":233.9,"dur":1.02,"text":"You drop the earpiece.","who":"narrator","scene":"call"},{"at":235.38,"dur":0.68,"text":"If I can see it...","who":"theo","scene":"call"},{"at":236.61,"dur":1.01,"text":"it's mine to fix.","who":"theo","scene":"call"},{"at":238.08,"dur":2.37,"text":"You call the one person on that beach you trust.","who":"narrator","scene":"call"},{"at":240.91,"dur":2.26,"text":"Grandpa. Kite. Up. Now.","who":"theo","scene":"call"},{"at":243.63,"dur":1.09,"text":"He doesn't ask why.","who":"narrator","scene":"call"},{"at":245.88,"dur":1.17,"text":"The red kite climbs.","who":"narrator","scene":"kite"},{"at":247.51,"dur":1.6,"text":"Left, Grandpa. More.","who":"theo","scene":"kite"},{"at":249.37,"dur":1.36,"text":"Stop. Hold it there.","who":"theo","scene":"kite"},{"at":251.19,"dur":1.45,"text":"Grandpa can't see the boy.","who":"narrator","scene":"kite"},{"at":252.9,"dur":1.27,"text":"But he can see his kite.","who":"narrator","scene":"kite"},{"at":254.43,"dur":2.11,"text":"And now it hangs right above that tiny head.","who":"narrator","scene":"kite"},{"at":257.7,"dur":1.5,"text":"You call the lifeguard station.","who":"narrator","scene":"nova"},{"at":259.46,"dur":0.81,"text":"Her name is Nova.","who":"narrator","scene":"nova"},{"at":260.73,"dur":0.86,"text":"Follow the red kite.","who":"theo","scene":"nova"},{"at":261.85,"dur":0.86,"text":"He's right under it.","who":"theo","scene":"nova"},{"at":263.17,"dur":1.45,"text":"Nova grabs the rescue board.","who":"narrator","scene":"nova"},{"at":264.88,"dur":1.49,"text":"She doesn't fight the current.","who":"narrator","scene":"nova"},{"at":266.63,"dur":0.84,"text":"She rides it out...","who":"narrator","scene":"nova"},{"at":268.02,"dur":1.15,"text":"then cuts sideways.","who":"narrator","scene":"nova"},{"at":269.43,"dur":1.26,"text":"And that's the real lesson.","who":"narrator","scene":"nova"},{"at":270.95,"dur":2.09,"text":"If a rip ever pulls you out, don't fight it.","who":"narrator","scene":"nova"},{"at":273.3,"dur":1.37,"text":"Swim parallel to the shore.","who":"narrator","scene":"nova"},{"at":274.93,"dur":1.07,"text":"Then come back in.","who":"narrator","scene":"nova"},{"at":277.16,"dur":2.61,"text":"Three minutes later, the boy is coughing on the sand.","who":"narrator","scene":"saved"},{"at":280.03,"dur":0.35,"text":"Alive...","who":"narrator","scene":"saved"},{"at":280.93,"dur":1.45,"text":"and furious about his board.","who":"narrator","scene":"saved"},{"at":282.64,"dur":2.41,"text":"The whole beach is cheering for an old man with a kite.","who":"narrator","scene":"saved"},{"at":286.21,"dur":0.99,"text":"And Mr. Black?","who":"narrator","scene":"police"},{"at":287.62,"dur":1.64,"text":"You never gave him a single number.","who":"narrator","scene":"police"},{"at":289.52,"dur":1.62,"text":"You gave the police something better.","who":"narrator","scene":"police"},{"at":291.4,"dur":0.53,"text":"His car.","who":"narrator","scene":"police"},{"at":292.19,"dur":0.62,"text":"His plate.","who":"narrator","scene":"police"},{"at":293.07,"dur":0.6,"text":"His face.","who":"narrator","scene":"police"},{"at":293.93,"dur":0.43,"text":"All read...","who":"narrator","scene":"police"},{"at":294.91,"dur":1.36,"text":"from two kilometers away.","who":"narrator","scene":"police"},{"at":296.53,"dur":1.5,"text":"Cover your PIN, by the way.","who":"narrator","scene":"police"},{"at":298.29,"dur":1.44,"text":"You never know who's watching.","who":"narrator","scene":"police"},{"at":300.89,"dur":1.75,"text":"That evening, you're back on the cliff.","who":"narrator","scene":"sunset"},{"at":302.9,"dur":1.58,"text":"Grandpa grips your shoulder.","who":"narrator","scene":"sunset"},{"at":304.94,"dur":1.2,"text":"Tell me what you see.","who":"grandpa","scene":"sunset"},{"at":306.6,"dur":2.99,"text":"For the first time in weeks, the world isn't just detail.","who":"narrator","scene":"sunset"},{"at":309.85,"dur":0.94,"text":"It's gold water.","who":"narrator","scene":"sunset"},{"at":311.05,"dur":0.61,"text":"A red kite.","who":"narrator","scene":"sunset"},{"at":311.92,"dur":1.49,"text":"And a family hugging a little boy.","who":"narrator","scene":"sunset"},{"at":313.67,"dur":0.57,"text":"Beautiful.","who":"narrator","scene":"sunset"},{"at":315.4,"dur":0.88,"text":"Is any of this real?","who":"narrator","scene":"real"},{"at":316.7,"dur":0.44,"text":"Partly.","who":"narrator","scene":"real"},{"at":317.4,"dur":3.59,"text":"Macular degeneration is real, and it steals central vision first.","who":"narrator","scene":"real"},{"at":321.25,"dur":1.41,"text":"Rip currents are real too.","who":"narrator","scene":"real"},{"at":322.92,"dur":1.69,"text":"But eyes a hundred times sharper?","who":"narrator","scene":"real"},{"at":325.03,"dur":1.03,"text":"Physics says no.","who":"narrator","scene":"real"},{"at":326.32,"dur":2.3,"text":"Light spreads out as it passes through your pupil.","who":"narrator","scene":"real"},{"at":328.88,"dur":1.82,"text":"A normal pupil is a few millimeters wide.","who":"narrator","scene":"real"},{"at":330.96,"dur":1.3,"text":"That's already near the limit.","who":"narrator","scene":"real"},{"at":332.52,"dur":1.31,"text":"A hundred times sharper?","who":"narrator","scene":"real"},{"at":334.25,"dur":2.06,"text":"You'd need pupils a hundred times wider.","who":"narrator","scene":"real"},{"at":336.57,"dur":1.36,"text":"Roughly thirty centimeters.","who":"narrator","scene":"real"},{"at":338.19,"dur":0.25,"text":"Eyes...","who":"narrator","scene":"real"},{"at":338.99,"dur":1,"text":"the size of pizzas.","who":"narrator","scene":"real"},{"at":340.25,"dur":2.73,"text":"Which, to be fair, would make birdwatching awkward.","who":"narrator","scene":"real"},{"at":344.14,"dur":1.78,"text":"That night, you look up at the Moon.","who":"narrator","scene":"sting"},{"at":346.18,"dur":1.6,"text":"And something on its surface...","who":"narrator","scene":"sting"},{"at":348.33,"dur":0.36,"text":"moves.","who":"narrator","scene":"sting"},{"at":349.85,"dur":2.45,"text":"So would you trade normal eyes for pizza-sized ones?","who":"narrator","scene":"cta"},{"at":352.72,"dur":0.93,"text":"What do you think?","who":"narrator","scene":"cta"},{"at":354.07,"dur":3.85,"text":"Tell us in the comments, and tell us which superpower we should do next.","who":"narrator","scene":"cta"},{"at":358.18,"dur":2.29,"text":"Hit like, and subscribe for Part Two.","who":"narrator","scene":"cta"}],"scenes":[{"id":"beach","t0":0,"t1":9.11},{"id":"moon","t0":9.11,"t1":14.9},{"id":"hill","t0":14.9,"t1":25.02},{"id":"plate","t0":25.02,"t1":33.39},{"id":"acuity","t0":33.39,"t1":39.91},{"id":"rule","t0":39.91,"t1":50.23},{"id":"title","t0":50.23,"t1":54.2},{"id":"class","t0":54.2,"t1":73.03},{"id":"stadium","t0":73.03,"t1":79.62},{"id":"birds","t0":79.62,"t1":85.85},{"id":"fovea","t0":85.85,"t1":108.51},{"id":"harbor","t0":108.51,"t1":118.73},{"id":"message","t0":118.73,"t1":131.95},{"id":"cost","t0":131.95,"t1":149.08},{"id":"grandpa","t0":149.08,"t1":162.84},{"id":"cliff","t0":162.84,"t1":182.75},{"id":"roof","t0":182.75,"t1":199.64},{"id":"sea","t0":199.64,"t1":224.63},{"id":"choice","t0":224.63,"t1":233.45},{"id":"call","t0":233.45,"t1":245.43},{"id":"kite","t0":245.43,"t1":257.25},{"id":"nova","t0":257.25,"t1":276.71},{"id":"saved","t0":276.71,"t1":285.76},{"id":"police","t0":285.76,"t1":300.44},{"id":"sunset","t0":300.44,"t1":314.95},{"id":"real","t0":314.95,"t1":343.69},{"id":"sting","t0":343.69,"t1":349.4},{"id":"cta","t0":349.4,"t1":365.23}]};
if (typeof module !== 'undefined') module.exports = TL; else globalThis.TIMELINE = TL; })();
